<script setup lang="ts">
import { ArrowRight, CalendarDays, Check, ChevronLeft, ChevronRight, CircleAlert, CircleHelp, Clock3, PackageCheck, Plus, RefreshCw, Repeat2, Search, ShoppingBag, Sparkles, UserPlus, Users, Wallet, X } from '@lucide/vue';
import { resolveProductImageUrl } from '~/shared/product-images';
const route=useRoute(); const router=useRouter(); const config=useRuntimeConfig(); const session=useB2BSession(); const {openContextMenu,copyText}=useContextMenu();
const profile=ref<any>(null),dashboard=ref<any>({}),clients=ref<any[]>([]),services=ref<any[]>([]),bookings=ref<any[]>([]),catalog=ref<any[]>([]),orders=ref<any[]>([]),tickets=ref<any[]>([]); const loading=ref(true),error=ref(''),notice=ref(''),dialog=ref(''); const search=ref(''); const cart=reactive<Record<string,number>>({}); const draft=reactive<any>({});
const {actionBusy:saving,runOperation}=useWorkspaceOperation(error);
const portalReady=ref(false),draftBaseline=ref(''),calendarMode=ref<'list'|'week'|'month'>('list'),calendarAnchor=ref(new Date());
const dialogDirty=computed(()=>Boolean(dialog.value)&&JSON.stringify(draft)!==draftBaseline.value);
const failedImages=ref<Record<string,string>>({});
function productImage(product:any){const image=resolveProductImageUrl(product.images?.[0]?.url,config.public.apiBase,String(config.public.siteUrl||''));return failedImages.value[product.id]===image?'':image;}
const calendarRange=computed(()=>{const from=new Date(calendarAnchor.value);from.setHours(0,0,0,0);if(calendarMode.value==='month')from.setDate(1);else if(calendarMode.value==='week')from.setDate(from.getDate()-((from.getDay()+6)%7));const to=new Date(from);if(calendarMode.value==='month')to.setMonth(to.getMonth()+1);else to.setDate(to.getDate()+(calendarMode.value==='week'?7:31));return {from,to};});
const calendarLabel=computed(()=>calendarMode.value==='month'?calendarRange.value.from.toLocaleDateString('ru-RU',{month:'long',year:'numeric'}):`${calendarRange.value.from.toLocaleDateString('ru-RU')} — ${new Date(calendarRange.value.to.getTime()-1).toLocaleDateString('ru-RU')}`);
function shiftCalendar(direction:number){const next=new Date(calendarAnchor.value);if(calendarMode.value==='month'){next.setDate(1);next.setMonth(next.getMonth()+direction);}else next.setDate(next.getDate()+direction*7);calendarAnchor.value=next;}
let loadVersion=0;
let loadController:AbortController|undefined;
const section=computed(()=>String(route.query.section||'dashboard')); const headers=computed(()=>({Authorization:`Bearer ${session.token.value}`}));
const titles:any={dashboard:['ЦЕНТР УПРАВЛЕНИЯ','Обзор бизнеса','Главное о салоне, клиентах, записи и закупках'],calendar:['РАБОЧИЙ КАЛЕНДАРЬ','Записи','Расписание клиентов и загрузка команды'],clients:['КЛИЕНТСКАЯ БАЗА','Мои клиенты','История посещений, контакты и заметки'],services:['ПРАЙС-ЛИСТ','Услуги и цены','Продолжительность, стоимость и доступность услуг'],catalog:['ПАРТНЁРСКИЙ КАТАЛОГ','Закупить товары','Персональные B2B-цены и актуальные остатки 1С'],orders:['ИСТОРИЯ ЗАКУПОК','Мои заказы','Статусы, состав и быстрый повтор заказа'],team:['ОРГАНИЗАЦИЯ','Команда','Сотрудники и права в кабинете'],support:['ПОМОЩЬ БИЗНЕСУ','Поддержка','Обращения к команде Sarkisian и контроль ответов']};
const currentTitle=computed(()=>titles[section.value]||titles.dashboard); const money=(v:any)=>v===null?'—':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(Number(v||0)); const dateTime=(v:any)=>new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); const statusLabels:any={NEW:'Новая',CONFIRMED:'Подтверждена',COMPLETED:'Завершена',CANCELLED:'Отменена',NO_SHOW:'Не пришёл',PAYMENT_WAITING:'Ожидает оплаты',PAID:'Оплачен',ASSEMBLING:'Собирается',SHIPPED:'Отправлен',DELIVERED:'Доставлен',REFUNDED:'Возврат',OPEN:'В работе',WAITING_REQUESTER:'Ожидает ответа',WAITING_CUSTOMER:'Ждём ответ',WAITING_INTERNAL:'На уточнении',RESOLVED:'Решена',CLOSED:'Закрыта'};
function fulfillmentLabel(item:any){if(item.oneCSyncError)return 'Ошибка передачи';if(item.packedAt)return 'Упакован';if(item.pickedAt)return 'Товар отобран';if(item.pickingStartedAt)return 'Собирается на складе';if(item.isSynced1C)return 'Передан в 1С';return 'В очереди 1С'}
const filteredClients=computed(()=>{const q=search.value.toLowerCase();return clients.value.filter(x=>`${x.firstName} ${x.lastName||''} ${x.phone||''} ${x.email||''}`.toLowerCase().includes(q))});
const cartLines=computed(()=>catalog.value.flatMap(p=>p.variants.filter((v:any)=>cart[v.id]).map((v:any)=>({product:p,variant:v,quantity:cart[v.id]})))); const cartTotal=computed(()=>cartLines.value.reduce((s,l)=>s+l.variant.b2bPrice*l.quantity,0));
async function api<T>(path:string,options:any={}){return $fetch<T>(path,{baseURL:config.public.apiBase,headers:headers.value,...options})}
async function load(){
  if(!portalReady.value||!session.token.value)return;
  const version=++loadVersion,identity=session.token.value;
  loadController?.abort();const controller=new AbortController();loadController=controller;
  loading.value=true;error.value='';
  const sectionSources:Record<string,string[]>={dashboard:['dashboard'],clients:['clients'],services:['services'],calendar:['clients','services','bookings'],catalog:['catalog'],orders:['orders'],team:[],support:['support']};
  const sources=['profile',...(sectionSources[section.value]||sectionSources.dashboard)];
  try{
    const result=await Promise.all(sources.map(source=>api<any>('/b2b/'+source,{signal:controller.signal,timeout:20000,...(source==='bookings'?{query:{from:calendarRange.value.from.toISOString(),to:calendarRange.value.to.toISOString()}}:{})})));
    if(version!==loadVersion||session.token.value!==identity)return;
    const targets:Record<string,Ref<any>>={profile,dashboard,clients,services,bookings,catalog,orders,support:tickets};
    sources.forEach((source,index)=>targets[source].value=result[index]);
  }catch(e:any){if(version===loadVersion&&!controller.signal.aborted)error.value=typeof e?.data?.message==='string'?e.data.message:'Не удалось загрузить раздел кабинета. Повторите попытку.';}
  finally{if(version===loadVersion)loading.value=false;}
}
function flash(value:string){notice.value=value;setTimeout(()=>notice.value='',2500);}
function resetDialog(){dialog.value='';draftBaseline.value='';}
function close(){if(saving.value)return false;if(dialogDirty.value&&!window.confirm('Закрыть форму без сохранения изменений?'))return false;resetDialog();return true;}
function open(type:string,value:any={}){if(!close())return;Object.keys(draft).forEach(key=>delete draft[key]);Object.assign(draft,JSON.parse(JSON.stringify(value)));draftBaseline.value=JSON.stringify(draft);dialog.value=type;error.value='';}
const {panel:dialogPanel,keyboard:dialogKeys}=useCatalogDialog(computed(()=>Boolean(dialog.value)),close);
onBeforeRouteLeave(()=>!saving.value&&(!dialogDirty.value||window.confirm('Есть несохранённые изменения. Покинуть кабинет?')));
onBeforeRouteUpdate(()=>{if(saving.value)return false;if(dialogDirty.value&&!window.confirm('Есть несохранённые изменения. Перейти в другой раздел?'))return false;resetDialog();return true;});
onBeforeUnmount(()=>{++loadVersion;loadController?.abort();});
watch(section,()=>{search.value='';load();});
watch([calendarMode,calendarAnchor],()=>{if(section.value==='calendar')load();});
async function saveClient(){await runOperation(async()=>{await api(draft.id?`/b2b/clients/${draft.id}`:'/b2b/clients',{method:draft.id?'PATCH':'POST',body:{firstName:draft.firstName,lastName:draft.lastName||undefined,phone:draft.phone||undefined,email:draft.email||undefined,notes:draft.notes||undefined,tags:String(draft.tags||'').split(',').map(value=>value.trim()).filter(Boolean),personalDataConsent:Boolean(draft.personalDataConsent)}});resetDialog();await load();flash('Клиент добавлен');});}
async function saveService(){await runOperation(async()=>{await api(draft.id?`/b2b/services/${draft.id}`:'/b2b/services',{method:draft.id?'PATCH':'POST',body:{name:draft.name,description:draft.description||undefined,duration:Number(draft.duration),price:Number(draft.price),color:draft.color||'#77709e'}});resetDialog();await load();flash('Услуга добавлена');});}
async function saveBooking(){await runOperation(async()=>{const start=new Date(draft.startTime);if(!Number.isFinite(start.getTime()))throw {data:{message:'Укажите корректную дату и время записи'}};await api('/b2b/bookings',{method:'POST',body:{clientId:draft.clientId,serviceId:draft.serviceId,masterMemberId:draft.masterMemberId||undefined,startTime:start.toISOString(),notes:draft.notes||undefined}});resetDialog();await load();flash('Запись создана');});}
async function bookingStatus(item:any,status:string){if(saving.value)return;if(status==='CANCELLED'&&!window.confirm('Отменить запись клиента?'))return;await runOperation(async()=>{await api(`/b2b/bookings/${item.id}`,{method:'PATCH',body:{status}});await load();flash(status==='COMPLETED'?'Визит завершён':'Статус записи обновлён');});}
async function checkout(){if(!cartLines.value.length||!profile.value?.membership?.canOrder)return;const completed=await runOperation(async()=>{const order:any=await api('/b2b/orders',{method:'POST',body:{items:cartLines.value.map(line=>({variantId:line.variant.id,quantity:line.quantity}))}});Object.keys(cart).forEach(key=>delete cart[key]);resetDialog();flash(`Заказ ${order.orderNumber} создан`);});if(completed){const failure=await router.push('/b2b?section=orders');if(!failure)await load();}}
async function repeatOrder(item:any){if(!profile.value?.membership?.canOrder||saving.value)return;if(!window.confirm('Создать новый заказ из этих позиций по актуальным ценам и остаткам?'))return;await runOperation(async()=>{await api(`/b2b/orders/${item.id}/repeat`,{method:'POST'});await load();flash('Повторный заказ создан');});}
async function saveSupport(){await runOperation(async()=>{await api('/b2b/support',{method:'POST',body:{subject:draft.subject,description:draft.description,priority:draft.priority||'MEDIUM'}});resetDialog();await load();flash('Обращение отправлено');});}
function clientMenu(e:MouseEvent,item:any){openContextMenu(e,`${item.firstName} ${item.lastName||''}`,[{label:'Редактировать клиента',icon:'open',action:()=>open('client',{...item,tags:(item.tags||[]).join(', '),personalDataConsent:Boolean(item.consentPersonalDataAt)})},{label:'Создать запись',icon:'open',action:()=>open('booking',{clientId:item.id})},{label:'Копировать телефон',icon:'copy',action:()=>copyText(item.phone||'','Телефон скопирован')}],item.phone||item.email||'Клиент')}
function orderMenu(e:MouseEvent,item:any){openContextMenu(e,item.orderNumber,[{label:'Повторить заказ',icon:'copy',action:()=>repeatOrder(item)},{label:'Копировать номер',icon:'copy',action:()=>copyText(item.orderNumber,'Номер заказа скопирован')}],statusLabels[item.status]||item.status)}
onMounted(async()=>{
  session.hydrate();
  if(!session.token.value)return navigateTo('/b2b-login');
  const restored=await session.restore();
  if(!restored)return navigateTo('/b2b-login');
  portalReady.value=true;
  await load();
});
</script>

<template><main data-v-ui-5c3d2dc5697c class="portal"><header data-v-ui-5c3d2dc5697c class="top"><div data-v-ui-5c3d2dc5697c><p data-v-ui-5c3d2dc5697c>{{currentTitle[0]}}</p><h1 data-v-ui-5c3d2dc5697c>{{currentTitle[1]}}</h1><span data-v-ui-5c3d2dc5697c>{{currentTitle[2]}}</span></div><div data-v-ui-5c3d2dc5697c class="top-actions"><button data-v-ui-5c3d2dc5697c @click="load"><RefreshCw data-v-ui-5c3d2dc5697c :size="15"/>Обновить</button><button data-v-ui-5c3d2dc5697c v-if="section==='clients'" class="primary" @click="open('client')"><UserPlus data-v-ui-5c3d2dc5697c :size="15"/>Новый клиент</button><button data-v-ui-5c3d2dc5697c v-else-if="section==='calendar'" class="primary" @click="open('booking')"><Plus data-v-ui-5c3d2dc5697c :size="15"/>Новая запись</button><button data-v-ui-5c3d2dc5697c v-else-if="section==='services'" class="primary" @click="open('service',{duration:60,color:'#77709e'})"><Plus data-v-ui-5c3d2dc5697c :size="15"/>Новая услуга</button><button data-v-ui-5c3d2dc5697c v-else-if="section==='support'" class="primary" @click="open('support',{priority:'MEDIUM'})"><Plus data-v-ui-5c3d2dc5697c :size="15"/>Обращение</button><button data-v-ui-5c3d2dc5697c v-else-if="section==='catalog'" class="primary" @click="open('cart')"><ShoppingBag data-v-ui-5c3d2dc5697c :size="15"/>Корзина · {{cartLines.length}}</button></div></header><div data-v-ui-5c3d2dc5697c v-if="loading" class="loading">Загружаем рабочее пространство…</div><div data-v-ui-5c3d2dc5697c v-else-if="error&&!dialog" class="page-error" role="alert"><span><CircleAlert :size="16"/>{{error}}</span><button type="button" class="b2b-retry" @click="load"><RefreshCw :size="16"/>Повторить загрузку</button></div><section data-v-ui-5c3d2dc5697c v-else class="body">

<template v-if="section==='dashboard'"><div data-v-ui-5c3d2dc5697c class="hero"><div data-v-ui-5c3d2dc5697c><p data-v-ui-5c3d2dc5697c>SARKISIAN BUSINESS</p><h2 data-v-ui-5c3d2dc5697c>{{profile?.name}}</h2><span data-v-ui-5c3d2dc5697c>Скидка партнёра {{profile?.discountTier||0}}% · {{profile?.status==='ACTIVE'?'организация активна':'профиль на модерации'}}</span></div><div data-v-ui-5c3d2dc5697c><b data-v-ui-5c3d2dc5697c>{{dashboard.bookingsToday||0}}</b><span data-v-ui-5c3d2dc5697c>записей сегодня</span></div></div><div data-v-ui-5c3d2dc5697c class="kpis"><article data-v-ui-5c3d2dc5697c><span data-v-ui-5c3d2dc5697c>Клиенты</span><b data-v-ui-5c3d2dc5697c>{{dashboard.clients||0}}</b><small data-v-ui-5c3d2dc5697c>в активной базе</small></article><article data-v-ui-5c3d2dc5697c><span data-v-ui-5c3d2dc5697c>Будущие записи</span><b data-v-ui-5c3d2dc5697c>{{dashboard.upcoming||0}}</b><small data-v-ui-5c3d2dc5697c>ожидают визита</small></article><article data-v-ui-5c3d2dc5697c><span data-v-ui-5c3d2dc5697c>Выручка услуг</span><b data-v-ui-5c3d2dc5697c>{{money(dashboard.serviceRevenueMonth)}}</b><small data-v-ui-5c3d2dc5697c>за текущий месяц</small></article><article data-v-ui-5c3d2dc5697c><span data-v-ui-5c3d2dc5697c>Закупки</span><b data-v-ui-5c3d2dc5697c>{{money(dashboard.purchasesMonth)}}</b><small data-v-ui-5c3d2dc5697c>{{dashboard.purchaseOrdersMonth||0}} заказов за месяц</small></article></div><div data-v-ui-5c3d2dc5697c class="dashboard-grid"><article data-v-ui-5c3d2dc5697c class="panel"><header data-v-ui-5c3d2dc5697c><div data-v-ui-5c3d2dc5697c><p data-v-ui-5c3d2dc5697c>БЛИЖАЙШЕЕ</p><h3 data-v-ui-5c3d2dc5697c>Следующие записи</h3></div><NuxtLink data-v-ui-5c3d2dc5697c to="/b2b?section=calendar">Весь календарь <ArrowRight data-v-ui-5c3d2dc5697c :size="14"/></NuxtLink></header><div data-v-ui-5c3d2dc5697c v-for="item in dashboard.nextBookings" :key="item.id" class="agenda"><time data-v-ui-5c3d2dc5697c>{{dateTime(item.startTime)}}</time><i data-v-ui-5c3d2dc5697c :style="{background:item.service.color}"></i><span data-v-ui-5c3d2dc5697c><b data-v-ui-5c3d2dc5697c>{{item.client.firstName}} {{item.client.lastName}}</b><small data-v-ui-5c3d2dc5697c>{{item.service.name}} · {{item.service.duration}} мин.</small></span><em data-v-ui-5c3d2dc5697c>{{statusLabels[item.status]}}</em></div><div data-v-ui-5c3d2dc5697c v-if="!dashboard.nextBookings?.length" class="empty">Ближайших записей нет</div></article><article data-v-ui-5c3d2dc5697c class="panel"><header data-v-ui-5c3d2dc5697c><div data-v-ui-5c3d2dc5697c><p data-v-ui-5c3d2dc5697c>ЗАКУПКИ</p><h3 data-v-ui-5c3d2dc5697c>Последние заказы</h3></div><NuxtLink data-v-ui-5c3d2dc5697c to="/b2b?section=catalog">В каталог <ArrowRight data-v-ui-5c3d2dc5697c :size="14"/></NuxtLink></header><div data-v-ui-5c3d2dc5697c v-for="item in dashboard.recentOrders" :key="item.id" class="order-mini"><span data-v-ui-5c3d2dc5697c><b data-v-ui-5c3d2dc5697c>{{item.orderNumber}}</b><small data-v-ui-5c3d2dc5697c>{{new Date(item.createdAt).toLocaleDateString('ru-RU')}} · {{item.items.length}} позиций</small></span><em data-v-ui-5c3d2dc5697c>{{money(item.finalAmount)}}</em></div><div data-v-ui-5c3d2dc5697c v-if="!dashboard.recentOrders?.length" class="empty">Заказов пока нет</div></article></div><div data-v-ui-5c3d2dc5697c class="quick"><button data-v-ui-5c3d2dc5697c @click="router.push('/b2b?section=calendar')"><CalendarDays data-v-ui-5c3d2dc5697c/><span data-v-ui-5c3d2dc5697c><b data-v-ui-5c3d2dc5697c>Управлять записью</b><small data-v-ui-5c3d2dc5697c>Календарь и загрузка мастеров</small></span><ArrowRight data-v-ui-5c3d2dc5697c/></button><button data-v-ui-5c3d2dc5697c @click="router.push('/b2b?section=clients')"><Users data-v-ui-5c3d2dc5697c/><span data-v-ui-5c3d2dc5697c><b data-v-ui-5c3d2dc5697c>Клиентская база</b><small data-v-ui-5c3d2dc5697c>Контакты и история визитов</small></span><ArrowRight data-v-ui-5c3d2dc5697c/></button><button data-v-ui-5c3d2dc5697c @click="router.push('/b2b?section=catalog')"><PackageCheck data-v-ui-5c3d2dc5697c/><span data-v-ui-5c3d2dc5697c><b data-v-ui-5c3d2dc5697c>Пополнить материалы</b><small data-v-ui-5c3d2dc5697c>{{dashboard.lowStock||0}} позиций требуют внимания</small></span><ArrowRight data-v-ui-5c3d2dc5697c/></button></div></template>

<template v-else-if="section==='clients'"><article data-v-ui-5c3d2dc5697c class="panel list-panel"><header data-v-ui-5c3d2dc5697c><div data-v-ui-5c3d2dc5697c><p data-v-ui-5c3d2dc5697c>БАЗА САЛОНА</p><h3 data-v-ui-5c3d2dc5697c>{{clients.length}} клиентов</h3></div><label data-v-ui-5c3d2dc5697c class="search"><Search data-v-ui-5c3d2dc5697c :size="15"/><input data-v-ui-5c3d2dc5697c v-model="search" placeholder="Имя, телефон или email"/></label></header><div data-v-ui-5c3d2dc5697c class="table clients"><div data-v-ui-5c3d2dc5697c class="row labels"><span data-v-ui-5c3d2dc5697c>Клиент</span><span data-v-ui-5c3d2dc5697c>Контакты</span><span data-v-ui-5c3d2dc5697c>Последний визит</span><span data-v-ui-5c3d2dc5697c>Посещения</span><span data-v-ui-5c3d2dc5697c>Сумма услуг</span></div><div data-v-ui-5c3d2dc5697c v-for="item in filteredClients" :key="item.id" class="row" @contextmenu.prevent="clientMenu($event,item)"><span data-v-ui-5c3d2dc5697c class="client"><i data-v-ui-5c3d2dc5697c>{{item.firstName.slice(0,1)}}</i><span class="b2b-client-name"><button type="button" class="b2b-edit-link" @click="open('client',{...item,tags:(item.tags||[]).join(', '),personalDataConsent:Boolean(item.consentPersonalDataAt)})"><b>{{item.firstName}} {{item.lastName}}</b></button><small data-v-ui-5c3d2dc5697c>{{item.tags?.join(', ')||'Без тегов'}}</small></span></span><span data-v-ui-5c3d2dc5697c>{{item.phone||item.email||'Не указаны'}}</span><span data-v-ui-5c3d2dc5697c>{{item.lastVisitAt?new Date(item.lastVisitAt).toLocaleDateString('ru-RU'):'Ещё не был'}}</span><span data-v-ui-5c3d2dc5697c>{{item.totalVisits}}</span><b data-v-ui-5c3d2dc5697c>{{money(item.totalSpent)}}</b></div><div data-v-ui-5c3d2dc5697c v-if="!filteredClients.length" class="empty">Добавьте первого клиента — его история будет собираться автоматически.</div></div></article></template>

