<template v-else-if="dialog==='booking'"><label data-v-ui-5c3d2dc5697c>Клиент<select data-v-ui-5c3d2dc5697c v-model="draft.clientId" required><option data-v-ui-5c3d2dc5697c value="" disabled>Выберите клиента</option><option data-v-ui-5c3d2dc5697c v-for="item in clients" :value="item.id">{{item.firstName}} {{item.lastName}}</option></select></label><label data-v-ui-5c3d2dc5697c>Услуга<select data-v-ui-5c3d2dc5697c v-model="draft.serviceId" required><option data-v-ui-5c3d2dc5697c value="" disabled>Выберите услугу</option><option data-v-ui-5c3d2dc5697c v-for="item in services.filter(x=>x.isActive)" :value="item.id">{{item.name}} · {{item.duration}} мин.</option></select></label><label data-v-ui-5c3d2dc5697c>Мастер<select data-v-ui-5c3d2dc5697c v-model="draft.masterMemberId"><option data-v-ui-5c3d2dc5697c value="">Не назначать</option><option data-v-ui-5c3d2dc5697c v-for="item in profile.members" :value="item.id">{{item.user.firstName}} {{item.user.lastName}}</option></select></label><label data-v-ui-5c3d2dc5697c>Дата и время<input data-v-ui-5c3d2dc5697c v-model="draft.startTime" type="datetime-local" required/></label><label data-v-ui-5c3d2dc5697c>Комментарий<textarea data-v-ui-5c3d2dc5697c v-model="draft.notes" rows="3"/></label></template>
<template v-else-if="dialog==='support'"><label data-v-ui-5c3d2dc5697c>Тема<input data-v-ui-5c3d2dc5697c v-model="draft.subject" required/></label><label data-v-ui-5c3d2dc5697c>Приоритет<select data-v-ui-5c3d2dc5697c v-model="draft.priority"><option data-v-ui-5c3d2dc5697c value="LOW">Низкий</option><option data-v-ui-5c3d2dc5697c value="MEDIUM">Обычный</option><option data-v-ui-5c3d2dc5697c value="HIGH">Высокий</option><option data-v-ui-5c3d2dc5697c value="CRITICAL">Критичный</option></select></label><label data-v-ui-5c3d2dc5697c>Опишите вопрос<textarea data-v-ui-5c3d2dc5697c v-model="draft.description" rows="7" required/></label></template>
<template v-else><div data-v-ui-5c3d2dc5697c class="checkout-lines"><div data-v-ui-5c3d2dc5697c v-for="line in cartLines"><span data-v-ui-5c3d2dc5697c>{{line.product.nameRu}}<small data-v-ui-5c3d2dc5697c>{{line.quantity}} шт.</small></span><b data-v-ui-5c3d2dc5697c>{{money(line.quantity*line.variant.b2bPrice)}}</b></div></div><div data-v-ui-5c3d2dc5697c class="checkout-total"><span data-v-ui-5c3d2dc5697c>К оплате</span><b data-v-ui-5c3d2dc5697c>{{money(cartTotal)}}</b></div><p data-v-ui-5c3d2dc5697c class="checkout-note">Заказ появится в системе обработки закупок. Передача в 1С зависит от настроенного подключения; её статус будет виден в заказе.</p></template>
</fieldset><p data-v-ui-5c3d2dc5697c v-if="error" class="form-error" role="alert">{{error}}</p></div><footer data-v-ui-5c3d2dc5697c><button data-v-ui-5c3d2dc5697c type="button" :disabled="saving" @click="close">Отмена</button><button data-v-ui-5c3d2dc5697c class="primary" :disabled="saving">{{saving?'Сохраняем…':dialog==='cart'?'Оформить заказ':'Сохранить'}}</button></footer></form></div><div data-v-ui-5c3d2dc5697c v-if="notice" class="toast">{{notice}}</div></main></template>
